<?php require 'common.php'; $mode=lab_mode(); $msg=$_GET['msg']??''; if(!isset($_SESSION['xss_csrf']))$_SESSION['xss_csrf']=bin2hex(random_bytes(32)); $message=''; if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['comment'])){ $comment=$_POST['comment']; if($mode==='fixed'&&!hash_equals($_SESSION['xss_csrf'],$_POST['csrf_token']??'')){http_response_code(403);$message='403: CSRF token invalid.';}else{$st=$ket_noi->prepare('INSERT INTO security_lab_comments(content) VALUES (?)');$st->execute([$comment]);audit('Stored XSS',$mode,'POST','/security-lab/xss.php',200,'stored','Fixed mode also requires CSRF token.');header('Location:xss.php?mode='.$mode);exit;}} $comments=$ket_noi->query('SELECT content,created_at FROM security_lab_comments ORDER BY id DESC LIMIT 10')->fetchAll(PDO::FETCH_ASSOC); audit('Reflected XSS',$mode,'GET',$_SERVER['REQUEST_URI']??'',200,'rendered','Compare vulnerable raw HTML output with fixed htmlspecialchars output.'); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>XSS Lab</title></head><body style="font-family:Arial;max-width:950px;margin:30px auto"><h1>Cross-Site Scripting Lab</h1><p>Mode: <b><?=h($mode)?></b></p><h2>Reflected XSS</h2><form><input name="msg" value="<?=h($msg)?>" size="60"><select name="mode"><option value="vulnerable" <?=$mode==='vulnerable'?'selected':''?>>vulnerable</option><option value="fixed" <?=$mode==='fixed'?'selected':''?>>fixed</option></select><button>Test</button></form><div style="padding:12px;border:1px solid #ccc;margin-top:10px"><?php if($mode==='vulnerable')echo $msg;else echo h($msg);?></div><h2>Stored XSS</h2><form method="post"><textarea name="comment" rows="4" cols="70"></textarea><?php if($mode==='fixed'):?><input type="hidden" name="csrf_token" value="<?=h($_SESSION['xss_csrf'])?>"><?php endif;?><br><button>Save comment</button></form><p><?=h($message)?></p><ul><?php foreach($comments as $c):?><li><?php echo $mode==='vulnerable'?$c['content']:h($c['content']);?> <small>(<?=h($c['created_at'])?>)</small></li><?php endforeach;?></ul><p><b>Fixed:</b> context-aware output encoding + CSRF protection + CSP.</p><p><a href="xss-dom.php">DOM XSS →</a> · <a href="audit.php">Audit log</a> · <a href="index.php">Lab menu</a></p></body></html>